//! Pinned oracle replays. Missing recordings are explicit until generated by
//! the coordinator; CI's --check step requires both fixture files.
#![allow(clippy::format_collect, reason = "test protocol hex encoding")]
use serde_json::Value as J;
use std::collections::BTreeMap;
use unityrs_core::{
    Bytes, File, RawStr,
    env::{EnvOptions, Environment, Source},
    limits::Meter,
};
use unityrs_mesh::{
    MeshError,
    obj::{self, ChargedBytes, MaterialView, MeteredWrite, ObjSink},
    read_mesh_for_obj,
};
#[path = "support/export_cases.rs"]
mod cases;
fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}
fn hex(b: &[u8]) -> String {
    b.iter().map(|b| format!("{b:02x}")).collect()
}
#[derive(Default)]
struct Sink(BTreeMap<String, String>);
impl ObjSink for Sink {
    fn file(
        &mut self,
        name: &[u8],
        ext: &'static str,
        f: &mut dyn FnMut(&mut dyn MeteredWrite) -> Result<(), MeshError>,
    ) -> Result<(), MeshError> {
        let mut out = ChargedBytes::new(&Meter::unlimited());
        f(&mut out)?;
        self.0.insert(
            format!("{}{ext}", String::from_utf8_lossy(name)),
            hex(out.as_bytes()),
        );
        Ok(())
    }
}
fn fixture(name: &str) -> Option<J> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    match std::fs::read(path) {
        Ok(b) => Some(serde_json::from_slice(&b).unwrap()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            eprintln!("oracle fixture {name} pending; run tools/fixtures/obj_export.py");
            None
        }
        Err(e) => panic!("{e}"),
    }
}
fn replay(c: &J, renderer: bool) {
    let env = Environment::new(EnvOptions::unitypy());
    let File::Serialized(file) = env
        .load(Source::Bytes {
            name: RawStr::from("synthetic.assets"),
            data: Bytes::from(unhex(c["input"].as_str().unwrap())),
        })
        .unwrap()
    else {
        panic!("file")
    };
    let object = file.object(c["target"].as_i64().unwrap()).unwrap();
    let meter = Meter::unlimited();
    if renderer {
        let mut sink = Sink::default();
        let result = obj::export_mesh_renderer(&object, &env, &meter, &mut sink);
        if c["corrected"].get("error").is_some() {
            assert!(result.is_err(), "{}", c["case"]);
            return;
        }
        result.unwrap();
        assert_eq!(
            serde_json::to_value(sink.0).unwrap(),
            c["corrected"]["files"],
            "{}",
            c["case"]
        );
        let mut materials = Vec::new();
        for object in file.objects().filter(|o| o.class_id() == 21) {
            let parsed = object.parse_as_dict(false).unwrap();
            let m = MaterialView::new(&parsed, object.file(), &env, &meter).unwrap();
            let mut out = ChargedBytes::new(&meter);
            obj::export_material(&m, &mut out).unwrap();
            materials.push(serde_json::json!({"value":hex(out.as_bytes())}));
        }
        assert_eq!(
            serde_json::json!(materials),
            c["corrected"]["materials"],
            "{}",
            c["case"]
        );
    } else {
        let names: Option<Vec<Option<RawStr>>> = c["materials"].as_array().map(|ns| {
            ns.iter()
                .map(|n| n.as_str().map(|n| RawStr::new(unhex(n))))
                .collect()
        });
        let refs: Option<Vec<Option<&RawStr>>> = names
            .as_ref()
            .map(|ns| ns.iter().map(Option::as_ref).collect());
        let result = read_mesh_for_obj(&object, &env, &meter)
            .and_then(|m| obj::export_mesh_obj_owned(&m, refs.as_deref(), &meter));
        if c["oracle"].get("error").is_some() {
            assert!(result.is_err(), "{}", c["case"]);
        } else {
            let got = result.unwrap();
            let value = got.map_or(J::Bool(false), |o| J::String(hex(o.as_bytes())));
            assert_eq!(value, c["oracle"]["value"], "{}", c["case"]);
        }
    }
}
#[test]
fn obj_text_equals_unitypy_oracle() {
    if let Some(f) = fixture("obj.json") {
        for c in f["cases"].as_array().unwrap() {
            replay(c, false);
        }
    }
}
#[test]
fn corrected_renderer_equals_oracle_and_divergence_mask() {
    if let Some(f) = fixture("renderer.json") {
        let mut mask = Vec::new();
        for c in f["cases"].as_array().unwrap() {
            assert_eq!(c["diverges"], c["oracle"] != c["corrected"]);
            mask.push((
                c["case"].as_str().unwrap(),
                c["diverges"].as_bool().unwrap(),
            ));
            if c["case"] == "unbatched_unity6" {
                assert_eq!(
                    c["oracle"]["error"], "TypeError",
                    "optional None must be exercised on a real MeshRenderer"
                );
            }
            replay(c, true);
        }
        assert_eq!(
            mask,
            [
                ("batch_offset", true),
                ("unbatched_unity6", true),
                ("legacy_subset", true),
                ("empty_subset", true),
                ("colors", true),
                ("textures", true),
                ("fast_keys", true),
                ("no_mesh", false),
                ("skinned", true),
                ("empty_texture_name", true),
            ]
        );
    }
}
#[test]
fn all_testkit_cases_reach_the_expected_rust_export() {
    for c in cases::cases() {
        let bytes = unityrs_testkit::scene3d::file(
            unityrs_testkit::scene3d::Layout::Unity6000,
            &[],
            &c.objects,
        )
        .unwrap();
        let env = Environment::new(EnvOptions::unitypy());
        let File::Serialized(file) = env
            .load(Source::Bytes {
                name: RawStr::from("synthetic.assets"),
                data: Bytes::from(bytes),
            })
            .unwrap()
        else {
            panic!("file")
        };
        let object = file.object(c.target).unwrap();
        let meter = Meter::unlimited();
        if c.kind == "renderer" {
            let mut output = Sink::default();
            if c.name == "empty_texture_name" {
                assert!(matches!(
                    obj::export_mesh_renderer(&object, &env, &meter, &mut output),
                    Err(MeshError::Field("unknown file extension: "))
                ));
                assert!(output.0.is_empty());
                continue;
            }
            obj::export_mesh_renderer(&object, &env, &meter, &mut output)
                .unwrap_or_else(|e| panic!("{}: {e}", c.name));
            if c.name == "skinned" {
                assert!(output.0.contains_key("m.obj"));
            }
            if c.name == "textures" || c.name == "fast_keys" {
                assert!(
                    output.0.contains_key("_MainTex.png"),
                    "raw duplicate texture entries must each be saved"
                );
                assert!(output.0.contains_key("_BumpMap.png"));
                let text = String::from_utf8(unhex(&output.0["m.mtl"])).unwrap();
                assert!(text.contains(
                    "map_Kd tex.png\nmap_bump _BumpMap.png\nbump _BumpMap.png\nmap_Ks tex.png"
                ));
            }
            if c.name == "colors" || c.name == "fast_keys" {
                let text = String::from_utf8(unhex(&output.0["m.mtl"])).unwrap();
                assert!(text.contains(
                    "Ka -0.0000 1.0000 2.0000\nKd 1.0000 0.0000 0.0000\nKs 0.1000 0.2000 0.3000"
                ));
            }
        } else {
            let names: Option<Vec<Option<RawStr>>> = c
                .names
                .map(|ns| ns.into_iter().map(|n| n.map(RawStr::new)).collect());
            let refs: Option<Vec<Option<&RawStr>>> = names
                .as_ref()
                .map(|ns| ns.iter().map(Option::as_ref).collect());
            let r = read_mesh_for_obj(&object, &env, &meter)
                .and_then(|m| obj::export_mesh_obj_owned(&m, refs.as_deref(), &meter));
            if ["lines", "points", "cut_triangle"].contains(&c.name) {
                assert!(r.is_err(), "{}", c.name);
            } else {
                let out = r.unwrap_or_else(|e| panic!("{}: {e}", c.name));
                if c.name == "compressed_int_zero_normals" {
                    let text = std::str::from_utf8(out.as_ref().unwrap().as_bytes()).unwrap();
                    assert!(text.contains("vn 0 0 0\n"), "{text}");
                }
            }
        }
    }
}

#[test]
fn renderer_rejects_surrogateescaped_text_while_raw_material_keeps_it() {
    for texture in [false, true] {
        let mut case = cases::cases()
            .into_iter()
            .find(|c| c.name == if texture { "textures" } else { "colors" })
            .unwrap();
        let index = if texture { 5 } else { 4 };
        unityrs_testkit::scene3d::set(
            &mut case.objects[index].value,
            "m_Name",
            unityrs_testkit::ngui::V::Str(b"bad\xff".to_vec()),
        );
        let bytes = unityrs_testkit::scene3d::file(
            unityrs_testkit::scene3d::Layout::Unity6000,
            &[],
            &case.objects,
        )
        .unwrap();
        let env = Environment::new(EnvOptions::unitypy());
        let File::Serialized(file) = env
            .load(Source::Bytes {
                name: RawStr::from("synthetic.assets"),
                data: Bytes::from(bytes),
            })
            .unwrap()
        else {
            panic!("file")
        };
        let meter = Meter::unlimited();
        let mat = file.object(5).unwrap();
        let parsed = mat.parse_as_dict(false).unwrap();
        let material = MaterialView::new(&parsed, mat.file(), &env, &meter).unwrap();
        let mut raw = ChargedBytes::new(&meter);
        obj::export_material(&material, &mut raw).unwrap();
        assert!(raw.as_bytes().contains(&0xff));
        assert!(
            obj::export_mesh_renderer(&file.object(3).unwrap(), &env, &meter, &mut Sink::default())
                .is_err()
        );
    }
}

#[test]
fn renderer_texture_platform_swap_matches_desktop_and_swizzle_is_refused() {
    use unityrs_testkit::ngui::V;
    let mut case = cases::cases()
        .into_iter()
        .find(|c| c.name == "textures")
        .unwrap();
    // Two-byte RGB565 samples: red then blue; both textures in all entries.
    for index in [5, 6] {
        let texture = &mut case.objects[index].value;
        unityrs_testkit::scene3d::set(texture, "m_TextureFormat", V::Int(7));
        unityrs_testkit::scene3d::set(texture, "m_Width", V::Int(1));
        unityrs_testkit::scene3d::set(texture, "m_Height", V::Int(1));
        unityrs_testkit::scene3d::set(texture, "image_data", V::Bytes(vec![0x00, 0xf8]));
    }
    let budget = std::sync::Arc::new(unityrs_core::budget::Unbounded);
    let (env, file) =
        support::load_with_platform(ngui_mesh_version(), &case.objects, budget.clone(), 13);
    let mut desktop = Sink::default();
    obj::export_mesh_renderer(
        &file.object(3).unwrap(),
        &env,
        &Meter::unlimited(),
        &mut desktop,
    )
    .unwrap();
    for index in [5, 6] {
        unityrs_testkit::scene3d::set(
            &mut case.objects[index].value,
            "image_data",
            V::Bytes(vec![0xf8, 0x00]),
        );
    }
    let (env, file) =
        support::load_with_platform(ngui_mesh_version(), &case.objects, budget.clone(), 11);
    let mut xbox = Sink::default();
    obj::export_mesh_renderer(
        &file.object(3).unwrap(),
        &env,
        &Meter::unlimited(),
        &mut xbox,
    )
    .unwrap();
    assert_eq!(desktop.0, xbox.0);
    let mut blob = vec![0; 12];
    blob[8] = 1;
    for index in [5, 6] {
        unityrs_testkit::scene3d::set(
            &mut case.objects[index].value,
            "m_PlatformBlob",
            V::Bytes(blob.clone()),
        );
    }
    let (env, file) = support::load_with_platform(ngui_mesh_version(), &case.objects, budget, 38);
    assert!(matches!(
        obj::export_mesh_renderer(
            &file.object(3).unwrap(),
            &env,
            &Meter::unlimited(),
            &mut Sink::default()
        ),
        Err(MeshError::Field("unsupported swizzled texture"))
    ));
}

#[test]
fn renderer_refuses_an_empty_texture_name_and_property_key() {
    let case = cases::cases()
        .into_iter()
        .find(|c| c.name == "empty_texture_name")
        .unwrap();
    let (env, file) = support::load(ngui_mesh_version(), &case.objects);
    let mut sink = Sink::default();
    assert!(matches!(
        obj::export_mesh_renderer(&file.object(3).unwrap(), &env, file.meter(), &mut sink),
        Err(MeshError::Field("unknown file extension: "))
    ));
    assert!(sink.0.is_empty());
    // Standalone material text never saves an image and still succeeds.
    let material = file.object(5).unwrap();
    let parsed = material.parse_as_dict(false).unwrap();
    let view = MaterialView::new(&parsed, material.file(), &env, file.meter()).unwrap();
    obj::export_material(&view, &mut ChargedBytes::new(file.meter())).unwrap();
}
fn ngui_mesh_version() -> unityrs_testkit::scene3d::mesh::MeshVersion {
    unityrs_testkit::scene3d::mesh::MeshVersion::V6000
}
mod support;
